import{_ as a,o as t,c as n,a2 as i}from"./chunks/framework.CDpkVv68.js";const g=JSON.parse('{"title":"Armor and mitigation","description":"","frontmatter":{},"headers":[],"relativePath":"en/game-design/combat/armor-and-mitigation.md","filePath":"en/game-design/combat/armor-and-mitigation.md"}'),o={name:"en/game-design/combat/armor-and-mitigation.md"};function r(d,e,s,l,c,m){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="armor-and-mitigation" tabindex="-1">Armor and mitigation <a class="header-anchor" href="#armor-and-mitigation" aria-label="Permalink to &quot;Armor and mitigation&quot;">​</a></h1><p><strong>Design status: Accepted localized coverage and shared-item durability; Experimental legacy adapter; Proposed material and condition interactions. Implementation: Stage 2A adapter, not the expanded material model below.</strong></p><p><a href="/Syrolands-Public/en/guide/combat/armor-and-protection.html">Player guide</a> · <a href="/Syrolands-Public/en/game-design/combat/overview.html">Combat foundations</a></p><h2 id="accepted-foundation-and-existing-bridge" tabindex="-1">Accepted foundation and existing bridge <a class="header-anchor" href="#accepted-foundation-and-existing-bridge" aria-label="Permalink to &quot;Accepted foundation and existing bridge&quot;">​</a></h2><p>Armor protects the region it covers and should protect both global health and local integrity, potentially through different calculations later. The current legacy armor adapter owns exact contact buckets, coverage weights, processing order and shared-item wear. Body regions are finer than legacy equipment: sleeves and leggings protect both sides through one item each; gloves are a shared pair for hand-related arm contacts.</p><p>The adapter resolves one actual contact, applies shield and selected-item mitigation once, and retains legacy virtual/magical mitigation. Missing armor does not cause a location reroll. Zero durability is not synonymous with deletion; an armor-breaking hit retains its mitigation and later hits may meet exposed coverage. Body integrity and item durability remain separate state. This is a bridge to the <a href="/Syrolands-Public/en/game-design/combat/damage.html">accepted experimental trauma policy</a>, not evidence of material-specific penetration or independently tuned trauma transmission.</p><h2 id="proposed-physical-interactions" tabindex="-1">Proposed physical interactions <a class="header-anchor" href="#proposed-physical-interactions" aria-label="Permalink to &quot;Proposed physical interactions&quot;">​</a></h2><p>Coverage, impact location, attack family, material, condition, penetration/deflection and transmitted trauma should all matter. A single generic AR score should not define the final model. The following are investigation directions, not resistance rankings or numerical tables:</p><table tabindex="0"><thead><tr><th>Armor family</th><th>Proposed tradeoff to investigate</th></tr></thead><tbody><tr><td>Plate</td><td>Cutting protection, deflection, deformation and transmitted impact versus burden</td></tr><tr><td>Mail</td><td>Coverage and flexible construction versus puncture and blunt transmission</td></tr><tr><td>Leather</td><td>Material and condition variation versus protection, weight and mobility</td></tr><tr><td>Cloth / padded / layered protection</td><td>Cushioning and layering versus cutting/puncture protection and burden</td></tr></tbody></table><p>For example, plate may stop cutting while transmitting blunt trauma. This does not specify how much, guarantee immunity, or authorize replacing the residual ×2 prototype with a second formula. Layer order, stacking limits and contact selection beyond the adapter remain Unresolved. Armor and weapon behavior should be evaluated together with <a href="/Syrolands-Public/en/game-design/combat/weapons-and-damage.html">damage families</a>.</p><h2 id="condition-inspection-and-maintenance" tabindex="-1">Condition, inspection and maintenance <a class="header-anchor" href="#condition-inspection-and-maintenance" aria-label="Permalink to &quot;Condition, inspection and maintenance&quot;">​</a></h2><p>Proposed condition effects include edge wear on weapons, deformation, weakened straps or seams, structural damage and reduced functional performance. They are examples of degradation, not newly implemented states. Existing item durability must not be reported as proof that all these forms are simulated.</p><p><a href="/Syrolands-Public/en/game-design/professions/blacksmithing.html">Blacksmithing</a> and <a href="/Syrolands-Public/en/game-design/professions/tailoring.html">Tailoring</a> supply proposed inspection, material knowledge and maintenance for their equipment domains. <a href="/Syrolands-Public/en/game-design/skills-and-knowledge.html">Arms Lore</a> provides combat equipment interpretation; expanded inspection is deferred. <a href="/Syrolands-Public/en/game-design/items/itemization-and-craft-quality.html#weapon-quality-dimensions">Craft quality</a> remains the owner of quality dimensions and Functional Retention, avoiding a competing durability model here.</p><p>Wear can create tactical opportunities without guaranteeing that armor breaks before a region becomes Disabled. Repairs, rare quality and traits must preserve <a href="/Syrolands-Public/en/game-design/equipment-and-loot.html">meaningful loss and replaceability</a>. No new retention or insurance rule is approved.</p><h2 id="related-design" tabindex="-1">Related design <a class="header-anchor" href="#related-design" aria-label="Permalink to &quot;Related design&quot;">​</a></h2><p><a href="/Syrolands-Public/en/game-design/combat/status-and-open-questions.html">Status and unresolved decisions</a></p>',16)])])}const h=a(o,[["render",r]]);export{g as __pageData,h as default};
